#### LCR 120. 寻找文件副本
(https://leetcode.cn/problems/shu-zu-zhong-zhong-fu-de-shu-zi-lcof/) 创建索引法：
```cpp
class Solution {
public:
    int findRepeatDocument(vector<int>& documents) {
        int i = 0;
        while(i < documents.size()) {
            if(documents[i] == i) {
                i++;
                continue;
            }
            if(documents[documents[i]] == documents[i])
                return documents[i];
            swap(documents[i],documents[documents[i]]);
        }
        return -1;
    }
};
```

